48|// The Chopin playlist, when the manifest defines it with tracks. The
49|// button stays hidden otherwise, and the player never persists the playlist.
50|function findChopinPlaylist(manifest: MusicManifest) {
51|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
