55|// Client container: cues music on scene entry only, from the route id.
56|// Sub-page moves never reach the scheduler. Params can lag a render, so
57|// the last observed id is compared before every observe call.
58|export function Reader({ scenes, children }: { scenes: SlimScene[]; children: React.ReactNode }) {
59|  const routeParams = useParams();
60|  const param = routeParams?.sceneId;
61|  const routeSceneId = typeof param === "string" ? param : null;
62|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
63|  const [selection, setSelection] = useState<MusicSelection | null>(null);
64|  const [musicFailed, setMusicFailed] = useState(false);
65|  const [currentId, setCurrentId] = useState<string | null>(null);
66|  const [replayNonce, setReplayNonce] = useState(0);
67|  const [fadeSec, setFadeSec] = useState(0);
68|  const [playlistOn, setPlaylistOn] = useState(false);
69|  // Volume and mute persist next to the style in one prefs object; the
70|  // player stays a controlled view over them. State starts at the server
71|  // defaults so hydration matches, then a mount effect applies stored
72|  // prefs (parsed once) to volume, muted, and style via prefsRef.
73|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
74|  const [muted, setMuted] = useState(false);
75|  const prefsRef = useRef<PersistedMusicPrefs | null>(null);
76|  // Ref mirrors so persist handlers always save fresh sound values.
77|  const volumeRef = useRef(volume);
78|  volumeRef.current = volume;
79|  const mutedRef = useRef(muted);
80|  mutedRef.current = muted;
81|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
82|  const schedRef = useRef<SchedulerState>(initScheduler());
83|  const historyRef = useRef<string[]>([]);
84|  const observedRef = useRef<string | null>(null);
85|  const liveRef = useRef({ routeSceneId, manifest, selection, currentId, byId, playlistOn });
86|  liveRef.current = { routeSceneId, manifest, selection, currentId, byId, playlistOn };
87|
88|  const nowSec = () => Date.now() / 1000;
89|
90|  const applyDecision = useCallback(
91|    (
92|      decision: {
93|        state: SchedulerState;
94|        switchToId: string | null;
95|        crossfadeSec: number;
96|      },
97|      opts?: { push?: boolean },
98|    ) => {
99|      // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
100|      // so bump a replay nonce the player effect listens to instead.
101|      const prevId = schedRef.current.currentId;
102|      schedRef.current = decision.state;
103|      if (decision.switchToId !== null) {
104|        setFadeSec(decision.crossfadeSec);
105|        if (decision.switchToId === prevId) {
106|          setReplayNonce((n) => n + 1);
107|        } else {
108|          // Every automatic switch banks the outgoing id for Previous.
109|          // The Previous handler passes push false so it never re-banks.
110|          if (opts?.push !== false && prevId !== null) {
111|            historyRef.current = pushHistory(historyRef.current, prevId);
112|          }
113|          setCurrentId(decision.switchToId);
114|        }
115|      }
116|    },
117|    [],
118|  );
119|
120|  const persist = useCallback((next: MusicSelection) => {
121|    setSelection(next);
122|    saveMusicPrefs({
123|      style: next.style,
124|      volume: volumeRef.current,
125|      muted: mutedRef.current,
126|    });
127|  }, []);
128|
129|  const observe = useCallback(
130|    (sceneId: string) => {
131|      const st = liveRef.current;
132|      if (!st.manifest || !st.selection) return;
133|      const signal = st.byId.get(sceneId) ?? null;
134|      applyDecision(
135|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
