242|    const st = liveRef.current;
243|    if (!st.manifest || !st.selection) return;
244|    const playlist = findChopinPlaylist(st.manifest);
245|    if (!playlist) return;
246|    if (st.playlistOn) {
247|      const signal = (st.routeSceneId && st.byId.get(st.routeSceneId)) || null;
