261|  function changeVolume(next: number) {
262|    setVolume(next);
263|    volumeRef.current = next;
264|    saveMusicPrefs({
265|      style: liveRef.current.selection?.style ?? null,
266|      volume: next,
267|      muted: mutedRef.current,
268|    });
269|  }
270|
271|  function changeMuted(next: boolean) {
272|    setMuted(next);
273|    mutedRef.current = next;
274|    saveMusicPrefs({
275|      style: liveRef.current.selection?.style ?? null,
276|      volume: volumeRef.current,
277|      muted: next,
278|    });
279|  }
280|
281|  function changeStyle(style: string) {
282|    const st = liveRef.current;
283|    if (!st.manifest || !st.selection || !st.routeSceneId || st.playlistOn) return;
284|    if (style === st.selection.style) return;
