313|    manifest !== null &&
314|    selection !== null &&
315|    (playlistOn
316|      ? (activePlaylist?.trackIds.length ?? 0) > 1
317|      : manifest.tracks.length > 1 &&
318|        nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null);
319|  // Previous restarts the track with no history (including the current
