26|export interface ScheduleDecision {
27|  state: SchedulerState;
28|  switchToId: string | null;
29|  crossfadeSec: number;
30|}
31|
32|export function initScheduler(): SchedulerState {
33|  return {
34|    currentId: null,
35|    currentStartedSec: 0,
36|    activeSceneId: null,
37|    pendingSceneId: null,
38|    pendingSinceSec: 0,
39|    overrideId: null,
40|    overrideSceneId: null,
41|    playlist: null,
42|  };
43|}
44|
45|function noChange(state: SchedulerState): ScheduleDecision {
46|  return { state, switchToId: null, crossfadeSec: 0 };
47|}
48|
49|function topRanked(
50|  signal: SceneSignal | null,
51|  manifest: MusicManifest,
52|  config: MusicConfig,
53|  excludeId?: string | null,
54|): { id: string; score: number } | null {
55|  if (signal === null) {
56|    const ids = [...manifest.tracks]
57|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
58|      .filter((t) => t.id !== excludeId);
59|    const first = ids[0];
60|    return first ? { id: first.id, score: 0 } : null;
61|  }
62|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
63|  const best = ranked[0];
64|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
65|}
66|
67|// Scheduled select: the draw keeps the current
68|// track when it is eligible, so rescans do not churn. Dwell is handled
69|// by promotion; min-track holds the current pick.
70|function evaluateRandom(
71|  state: SchedulerState,
72|  signal: SceneSignal,
73|  styleTracks: Track[],
74|  scoped: MusicManifest,
75|  nowSec: number,
76|  config: MusicConfig,
77|  env: SelectEnv,
78|): ScheduleDecision {
79|  const pick = pickRandomTrack(styleTracks, signal, state.currentId, env.rng, config);
80|  if (!pick || pick.id === state.currentId) return noChange(state);
81|  if (state.currentId !== null && nowSec - state.currentStartedSec < config.minTrackSec) {
82|    return noChange(state);
83|  }
84|  return {
85|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
86|    switchToId: pick.id,
87|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
88|  };
89|}
90|
91|function evaluateSwitch(
92|  state: SchedulerState,
93|  signal: SceneSignal | null,
94|  manifest: MusicManifest,
95|  nowSec: number,
96|  config: MusicConfig,
97|  env: SelectEnv,
98|): ScheduleDecision {
99|  if (signal === null) return noChange(state);
100|  if (state.playlist !== null) return noChange(state);
101|  const styleTracks = candidatesFor(env.selection, manifest);
102|  if (styleTracks.length === 0) return noChange(state);
103|  const scoped = { ...manifest, tracks: styleTracks };
104|  return evaluateRandom(state, signal, styleTracks, scoped, nowSec, config, env);
