106|
107|function promote(
108|  state: SchedulerState,
109|  sceneId: string,
110|  signal: SceneSignal | null,
111|  manifest: MusicManifest,
112|  nowSec: number,
113|  config: MusicConfig,
114|  env: SelectEnv,
115|): ScheduleDecision {
116|  const settled: SchedulerState = {
117|    ...state,
118|    activeSceneId: sceneId,
119|    pendingSceneId: null,
120|    pendingSinceSec: 0,
121|    overrideId: null,
122|    overrideSceneId: null,
123|  };
124|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
125|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
