128|// The reading position entered a scene. It becomes pending and the dwell
129|// clock restarts, so fast scrolling keeps only the newest scene. After
130|// the pending scene holds for dwellSec it becomes active. The first
131|// track ever plays at once, with no dwell.
132|export function observeScene(
133|  state: SchedulerState,
134|  sceneId: string,
135|  signal: SceneSignal | null,
136|  manifest: MusicManifest,
137|  nowSec: number,
138|  env: SelectEnv,
139|  override?: Partial<MusicConfig>,
140|): ScheduleDecision {
141|  const config = resolveConfig(override ?? MUSIC_CONFIG);
142|  if (state.currentId === null) {
143|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
144|  }
145|  if (sceneId === state.activeSceneId) {
146|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
147|  }
148|  if (sceneId !== state.pendingSceneId) {
149|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
150|  }
151|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
152|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
153|}
154|
155|// Time passed: settle a pending scene whose dwell has expired, or
156|// re-check the active scene (a hold from minTrackSec may have expired).
157|// The reader passes the pending signal when one exists, else the active.
158|export function tickScheduler(
159|  state: SchedulerState,
160|  signal: SceneSignal | null,
161|  manifest: MusicManifest,
162|  nowSec: number,
163|  env: SelectEnv,
164|  override?: Partial<MusicConfig>,
165|): ScheduleDecision {
166|  const config = resolveConfig(override ?? MUSIC_CONFIG);
167|  if (state.currentId === null) return noChange(state);
168|  if (state.pendingSceneId !== null) {
169|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
170|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
171|  }
172|  // A skip override holds until the next scene change; promotion clears it.
173|  if (state.overrideId !== null) return noChange(state);
174|  if (state.activeSceneId === null) return noChange(state);
175|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
176|}
177|
178|// Reader skip: the same-emotion Next rule, applied at once with the
179|// normal crossfade. The choice holds until the next scene change.
180|export function requestNext(
181|  state: SchedulerState,
182|  signal: SceneSignal | null,
183|  manifest: MusicManifest,
184|  nowSec: number,
185|  env: SelectEnv,
186|  override?: Partial<MusicConfig>,
187|): ScheduleDecision {
188|  const config = resolveConfig(override ?? MUSIC_CONFIG);
189|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
190|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
191|  if (!next) return noChange(state);
192|  return {
193|    state: {
194|      ...state,
195|      currentId: next.id,
196|      currentStartedSec: nowSec,
197|      overrideId: next.id,
198|      overrideSceneId: state.activeSceneId,
199|    },
200|    switchToId: next.id,
201|    crossfadeSec: config.crossfadeSec,
202|  };
203|}
204|
205|// Manual pick from Previous: the track holds like a Next until the next
206|// scene change. Unknown ids change nothing.
207|export function requestManualTrack(
208|  state: SchedulerState,
209|  manifest: MusicManifest,
210|  trackId: string,
211|  nowSec: number,
212|  override?: Partial<MusicConfig>,
213|): ScheduleDecision {
214|  const config = resolveConfig(override ?? MUSIC_CONFIG);
215|  if (state.playlist !== null) return noChange(state);
216|  const picked = manifest.tracks.find((t) => t.id === trackId) ?? null;
217|  if (!picked) return noChange(state);
218|  return {
219|    state: {
220|      ...state,
221|      currentId: picked.id,
222|      currentStartedSec: nowSec,
223|      overrideId: picked.id,
224|      overrideSceneId: state.activeSceneId,
225|    },
226|    switchToId: picked.id,
227|    crossfadeSec: config.crossfadeSec,
