231|// A non-looping track ended: fade into the best remaining track,
232|// excluding the one that just ended. Never crosses styles.
233|export function noteTrackEnded(
234|  state: SchedulerState,
235|  signal: SceneSignal | null,
236|  manifest: MusicManifest,
237|  endedId: string,
238|  nowSec: number,
239|  env: SelectEnv,
240|  override?: Partial<MusicConfig>,
241|): ScheduleDecision {
242|  const config = resolveConfig(override ?? MUSIC_CONFIG);
243|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
244|  const styleTracks = candidatesFor(env.selection, manifest).filter((t) => t.id !== endedId);
245|  if (styleTracks.length === 0) return noChange(state);
246|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
247|  if (!best) return noChange(state);
248|  return {
249|    state: {
250|      ...state,
251|      currentId: best.id,
252|      currentStartedSec: nowSec,
253|      overrideId: null,
254|      overrideSceneId: null,
255|    },
256|    switchToId: best.id,
257|    crossfadeSec: config.crossfadeSec,
258|  };
259|}
