261|// Fixed playlist mode (the Chopin easter egg). Playlist order lives here
262|// because it reuses SchedulerState and the crossfade config.
263|function playlistById(manifest: MusicManifest, id: string) {
264|  return manifest.playlists.find((p) => p.id === id) ?? null;
265|}
266|
267|// Enter playlist mode: switch at once to the first track, with no dwell
268|// and no min-track rule. Scene changes stay tracked but never switch.
269|export function enterPlaylist(
270|  state: SchedulerState,
271|  manifest: MusicManifest,
272|  playlistId: string,
273|  nowSec: number,
274|  override?: Partial<MusicConfig>,
275|): ScheduleDecision {
276|  const config = resolveConfig(override ?? MUSIC_CONFIG);
277|  const playlist = playlistById(manifest, playlistId);
278|  const firstId = playlist?.trackIds[0];
279|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
280|  if (!playlist || !first) return noChange(state);
281|  return {
282|    state: {
283|      ...state,
284|      currentId: first.id,
285|      currentStartedSec: nowSec,
286|      overrideId: null,
287|      overrideSceneId: null,
288|      playlist: { id: playlist.id, index: 0 },
289|    },
290|    switchToId: first.id,
291|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
292|  };
293|}
294|
295|// Next playlist track in trackIds order, wrapping last to first. Used by
296|// both the end-of-track path and the Next button while the playlist is on.
297|function advancePlaylist(
298|  state: SchedulerState,
299|  manifest: MusicManifest,
300|  nowSec: number,
301|  config: MusicConfig,
302|): ScheduleDecision {
303|  if (state.playlist === null) return noChange(state);
304|  const playlist = playlistById(manifest, state.playlist.id);
305|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
306|  // A one-track playlist wraps onto the same id. That still returns a
307|  // switch so the ended element re-cues instead of going quiet.
308|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
309|  const nextId = playlist.trackIds[nextIndex];
310|  if (nextId === undefined) return noChange(state);
311|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
312|  if (!next) return noChange(state);
313|  return {
314|    state: {
315|      ...state,
316|      currentId: next.id,
317|      currentStartedSec: nowSec,
318|      overrideId: null,
319|      overrideSceneId: null,
320|      playlist: { id: playlist.id, index: nextIndex },
321|    },
322|    switchToId: next.id,
323|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
324|  };
325|}
326|
327|// Leave playlist mode: clear the playlist state and switch at once to the
328|// best match for the current scene under the restored selection.
329|export function exitPlaylist(
330|  state: SchedulerState,
331|  signal: SceneSignal | null,
332|  manifest: MusicManifest,
333|  nowSec: number,
334|  env: SelectEnv,
335|  override?: Partial<MusicConfig>,
336|): ScheduleDecision {
337|  if (state.playlist === null) return noChange(state);
338|  const config = resolveConfig(override ?? MUSIC_CONFIG);
339|  const styleTracks = candidatesFor(env.selection, manifest);
340|  const cleared: SchedulerState = {
341|    ...state,
342|    overrideId: null,
343|    overrideSceneId: null,
344|    playlist: null,
345|  };
346|  const best = topRanked(signal, { ...manifest, tracks: styleTracks }, config);
347|  if (!best) return { ...noChange(cleared), state: cleared };
348|  return {
349|    state: { ...cleared, currentId: best.id, currentStartedSec: nowSec },
350|    switchToId: best.id,
351|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
352|  };
353|}
354|
355|// Style change from user action: switches at once with the normal
356|// crossfade, no dwell and no min-track rule, and sets the override like
357|// Next.
358|export function switchStyle(
359|  state: SchedulerState,
360|  signal: SceneSignal | null,
361|  manifest: MusicManifest,
362|  nowSec: number,
363|  style: string,
364|  override?: Partial<MusicConfig>,
365|): ScheduleDecision {
366|  // The reader blocks style changes while a playlist plays. The guard
367|  // keeps the saved index pointing at the current track if one slips by.
368|  if (state.playlist !== null) return noChange(state);
369|  const config = resolveConfig(override ?? MUSIC_CONFIG);
370|  const picked = requestStyleChange(manifest, style, signal, config);
371|  if (!picked) return noChange(state);
372|  return {
373|    state: {
374|      ...state,
375|      currentId: picked.track.id,
376|      currentStartedSec: nowSec,
377|      overrideId: picked.track.id,
378|      overrideSceneId: state.activeSceneId,
379|    },
380|    switchToId: picked.track.id,
381|    crossfadeSec: config.crossfadeSec,
382|  };
383|}
384|
385|export { MUSIC_CONFIG };

