193|      const st = liveRef.current;
194|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
195|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
196|      const signal = st.byId.get(sceneId) ?? null;
197|      applyDecision(
198|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
199|          selection: st.selection,
200|          rng: Math.random,
201|        }, entryDwell()),
202|      );
203|    }, 1000);
204|    return () => window.clearInterval(timer);
205|  }, [applyDecision]);
206|
207|  function skip() {
208|    const st = liveRef.current;
209|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
210|    const signal = st.byId.get(st.routeSceneId) ?? null;
211|    applyDecision(
212|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
213|        selection: st.selection,
214|        rng: Math.random,
215|      }),
