1|// Track similarity and ranking. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|import type {
6|  MusicConfig,
7|  MusicManifest,
8|  MusicWeights,
9|  SceneSignal,
10|  Similarity,
11|  Track,
12|} from "./music-types";
13|
14|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
15|// "unknown" entry) are ignored. An all-zero vector stays all zero.
16|export function normalize8(vector: Record<string, number>): number[] {
17|  const values = EMOTIONS.map((id: EmotionId) => {
18|    const v = vector[id];
19|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
20|  });
21|  const sum = values.reduce((a, b) => a + b, 0);
22|  if (sum <= 0) return values.map(() => 0);
23|  return values.map((v) => v / sum);
24|}
25|
26|// Bhattacharyya affinity over the renormalized shapes, plus separate
27|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
28|export function bhattacharyyaSimilarity(
29|  scene: SceneSignal,
30|  track: Track,
31|  weights: MusicWeights = MUSIC_CONFIG.weights,
32|): number {
33|  const s = normalize8(scene.vector);
34|  const t = normalize8(track.vector);
35|  let affinity = 0;
36|  for (let i = 0; i < s.length; i++) {
37|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
38|  }
39|  return (
40|    weights.emotion * affinity +
41|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
42|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
43|  );
44|}
45|
46|// Cosine over buildFeatures output (vector plus weighted intensity and
47|// tempo). Kept as an alternative; it favors peaky scenes.
48|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
49|  const a = buildFeatures(scene);
50|  const b = buildFeatures(track);
51|  let dot = 0;
52|  let na = 0;
53|  let nb = 0;
54|  for (let i = 0; i < a.length; i++) {
55|    const x = a[i] ?? 0;
56|    const y = b[i] ?? 0;
57|    dot += x * y;
58|    na += x * x;
59|    nb += y * y;
60|  }
61|  if (na === 0 || nb === 0) return 0;
62|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
63|}
64|
65|export const MUSIC_CONFIG: MusicConfig = {
66|  similarity: bhattacharyyaSimilarity,
67|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
68|  dwellSec: 20,
69|  sceneEntryDwellSec: 5,
70|  minTrackSec: 45,
71|  crossfadeSec: 3,
72|  // Admits near ties into the random-mode draw without letting clearly
73|  // worse matches in.
74|  randomTolerance: 0.05,
75|};
76|
77|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
78|  if (!override) return MUSIC_CONFIG;
79|  return {
80|    ...MUSIC_CONFIG,
81|    ...override,
82|    weights: override.weights ?? MUSIC_CONFIG.weights,
83|  };
84|}
85|
86|export function scoreTrack(
87|  scene: SceneSignal,
88|  track: Track,
89|  override?: Partial<MusicConfig>,
90|): number {
91|  const config = resolveConfig(override);
92|  return config.similarity(scene, track, config.weights);
93|}
94|
95|// Best score first. Ties go to the lower track id, so ranking is stable.
96|export function rankTracks(
97|  scene: SceneSignal,
98|  manifest: MusicManifest,
99|  override?: Partial<MusicConfig>,
100|): Track[] {
101|  const config = resolveConfig(override);
102|  return [...manifest.tracks].sort((a, b) => {
103|    const diff =
104|      config.similarity(scene, b, config.weights) - config.similarity(scene, a, config.weights);
105|    if (diff !== 0) return diff;
106|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
107|  });
108|}
109|
110|// Dominant emotion of a scene: argmax of the renormalized vector, with
111|// ties broken by EMOTIONS order.
112|export function dominantEmotion(scene: SceneSignal): EmotionId {
113|  const norm = normalize8(scene.vector);
114|  let best: EmotionId = EMOTIONS[0] as EmotionId;
115|  let bestValue = -Infinity;
116|  EMOTIONS.forEach((id: EmotionId, i: number) => {
117|    const value = norm[i] ?? 0;
118|    if (value > bestValue) {
119|      bestValue = value;
120|      best = id;
121|    }
122|  });
123|  return best;
124|}

