1|// Pure playback math for app/player.tsx. Gain matches loudness without
2|// re-encoding; the effective end stops or loops a labeled segment.
3|export function gainVolume(level: number, volume: number, gainDb: number): number {
4|  return Math.min(1, Math.max(0, level * volume * 10 ** (gainDb / 20)));
5|}
6|
7|// A missing endSec means the media end, so the file duration wins.
8|export function effectiveEnd(endSec: number | undefined, duration: number): number {
9|  return Math.min(endSec ?? Infinity, duration);
