1|// Pre-commit size check: staged files must stay under 5000 tokens.
2|// Tokens = ceil(bytes / 4). Plain Node, no dependencies.
3|import { execFileSync } from 'node:child_process';
4|import { fileURLToPath } from 'node:url';
5|
6|export const MAX_TOKENS = 5000;
7|export const BYTES_PER_TOKEN = 4;
8|
9|// Paths the size check skips. Entries ending in "/" match that directory
10|// anywhere in the path. Entries with "*" match the file name. Other entries
11|// match the full path or the file name. Add a pattern here (and say why in
12|// the commit message) when a file really is generated or third-party.
13|export const IGNORE_PATTERNS = [
14|  // Lockfiles: not authored by agents.
15|  'package-lock.json',
16|  'pnpm-lock.yaml',
17|  'yarn.lock',
18|  'bun.lockb',
19|  'uv.lock',
20|  'poetry.lock',
21|  '*.lock',
22|  // Codegen: generated dirs cover their *.d.ts files too.
23|  '*.generated.*',
24|  '*.gen.*',
25|  'next-env.d.ts',
26|  'generated/',
27|  '__generated__/',
28|  // Build output.
29|  '.next/',
30|  'dist/',
31|  'out/',
32|  'coverage/',
33|  // Processed book data, and all of public/.
34|  'public/',
35|  'data/processed/',
36|  // Processed book data (book.json is generated, about 230 KB).
37|  'data/books/',
38|  'pipeline/out/',
39|  // Music library data: track metadata and an etiquetar export, not code.
40|  'data/music/',
41|  // Agent and session logs (the project log dir is agent-logs/).
42|  'agent-logs/',
43|  // Vendored third-party skills.
44|  '.agents/skills/',
45|];
46|
47|function globToRegExp(glob) {
48|  return new RegExp('^' + glob.split('*').map(escapeRegExp).join('.*') + '$');
49|}
50|
51|function escapeRegExp(text) {
52|  return text.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
53|}
54|
55|function basename(path) {
56|  const index = path.lastIndexOf('/');
57|  return index === -1 ? path : path.slice(index + 1);
58|}
59|
60|export function isIgnored(path) {
61|  const name = basename(path);
62|  for (const pattern of IGNORE_PATTERNS) {
63|    if (pattern.endsWith('/')) {
64|      if (path === pattern.slice(0, -1) || path.startsWith(pattern) || path.includes('/' + pattern)) {
65|        return true;
66|      }
67|    } else if (pattern.includes('*')) {
68|      if (globToRegExp(pattern).test(name)) return true;
69|    } else if (path === pattern || name === pattern || path.endsWith('/' + pattern)) {
70|      return true;
71|    }
72|  }
73|  return false;
74|}
75|
76|export function estimateTokens(bytes) {
77|  return Math.ceil(bytes / BYTES_PER_TOKEN);
78|}
79|
80|// Pure and testable: entries look like { path, bytes, isBinary }.
81|export function findOversized(entries) {
82|  const oversized = [];
83|  for (const entry of entries) {
84|    if (entry.isBinary || isIgnored(entry.path)) continue;
85|    const tokens = estimateTokens(entry.bytes);
86|    if (tokens > MAX_TOKENS) oversized.push({ path: entry.path, bytes: entry.bytes, tokens });
87|  }
88|  return oversized;
89|}
90|
91|export const SPLIT_HELP = `How to split it:
92|- Split by responsibility into small modules, one concern per file, roughly under 300 lines.
93|- Put shared types in their own file.
94|- Move fixtures and test data to fixtures/ or public/.
95|- For TS/JS create a folder with an index.ts that re-exports the pieces so imports stay stable.
96|- For docs split by heading into docs/<topic>/*.md with a short index.
97|- For tests split per behavior.
98|- Never minify or remove comments to sneak under the limit.
99|- If the file really is generated or third-party, add its pattern to the ignore list in this script and explain why in the commit message.`;
100|
101|function stagedPaths() {
102|  const output = execFileSync(
103|    'git',
104|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
105|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
106|  );
107|  const text = output.toString('utf8');
108|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
109|}
110|
111|// Pure and testable: flags from `git diff --numstat -z` output. Each record is
112|// one NUL-terminated "added\tdeleted\tpath" chunk; a rename is a chunk with
113|// an empty path followed by old-name and new-name chunks, keyed on the new.
114|export function parseNumstatZ(text) {
115|  const flags = new Map();
116|  if (text.length === 0) return flags;
117|  const parts = text.split('\0');
118|  for (let i = 0; i < parts.length; i++) {
119|    const chunk = parts[i];
120|    if (chunk === '') continue;
121|    const record = /^(\d+|-)\t(\d+|-)\t([\s\S]*)$/.exec(chunk);
122|    if (!record) continue;
123|    const isBinary = record[1] === '-' && record[2] === '-';
124|    let path = record[3];
125|    if (path === '') {
126|      const renamed = parts[i + 2];
127|      i += 2;
128|      if (renamed === undefined || renamed === '') continue;
129|      path = renamed;
130|    }
131|    flags.set(path, isBinary);
132|  }
133|  return flags;
134|}
135|
136|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
137|// first 8000 bytes hold a NUL byte, so this reuses that detection.
138|function stagedBinaryFlags() {
139|  const output = execFileSync(
140|    'git',
141|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
142|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
143|  );
144|  return parseNumstatZ(output.toString('utf8'));
145|}
146|
147|function stagedBlobSize(path) {
148|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
149|    encoding: 'utf8',
150|    stdio: ['ignore', 'pipe', 'ignore'],
151|  });
152|  return Number.parseInt(output.trim(), 10);
153|}
154|
155|function main() {
156|  let paths;
157|  let binaryFlags = new Map();
158|  try {
159|    paths = stagedPaths();
160|    binaryFlags = stagedBinaryFlags();
161|  } catch {
162|    console.error('warning: not a git repo, skipping the file-size check');
163|    return 0;
164|  }
165|  const entries = [];
166|  for (const path of paths) {
167|    if (isIgnored(path)) continue;
168|    let bytes;
169|    try {
170|      bytes = stagedBlobSize(path);
171|    } catch {
172|      continue; // Left the index since the diff was read.
173|    }
174|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
175|  }
176|  const oversized = findOversized(entries);
177|  if (oversized.length === 0) return 0;
178|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
179|  for (const file of oversized) {
180|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
181|  }
182|  console.error('');
183|  console.error(SPLIT_HELP);
184|  return 1;
185|}
186|
187|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
188|if (invokedAsScript) process.exit(main());

